"use strict";
const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api), ["encodeFields"]);
const { encodeFields } = api;

for (const bad of [undefined, null, "x", {}, ["x", 1], [null], ["x", undefined]]) {
  assert.throws(() => encodeFields(bad), TypeError);
}
assert.equal(encodeFields([]), "");
assert.equal(encodeFields([""]), "\"\"");
assert.equal(encodeFields(["alpha", "beta"]), "\"alpha\";\"beta\"");
assert.equal(encodeFields(["a\"b\"c"]), "\"a\\\"b\\\"c\"");
assert.equal(encodeFields(["a\\b"]), "\"a\\\\b\"");
assert.equal(encodeFields(["\\\""]), "\"\\\\\\\"\"");
assert.equal(encodeFields([";", "x;y"]), "\";\";\"x;y\"");
const fields = ["one", "two\\\"three"];
const copy = fields.slice();
encodeFields(fields);
assert.deepStrictEqual(fields, copy);

